create extension if not exists pgcrypto;
create type public.task_status as enum ('todo','in_progress','review','done','canceled');
create type public.task_priority as enum ('low','medium','high','urgent');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.projects (id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade, name text not null check(char_length(name) between 1 and 100), color text not null default '#00ae9d', archived_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tasks (id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade, project_id uuid references public.projects(id) on delete set null, title text not null check(char_length(title) between 1 and 200), description text, status public.task_status not null default 'todo', priority public.task_priority not null default 'medium', position numeric not null default 1000, start_at timestamptz, due_at timestamptz, completed_at timestamptz, archived_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tags (id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade, name text not null, color text not null default '#7db61c', unique(owner_id,name));
create table public.task_tags (task_id uuid references public.tasks(id) on delete cascade, tag_id uuid references public.tags(id) on delete cascade, primary key(task_id,tag_id));
create table public.checklist_items (id uuid primary key default gen_random_uuid(), task_id uuid not null references public.tasks(id) on delete cascade, owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade, title text not null, is_completed boolean not null default false, position numeric not null default 1000, created_at timestamptz not null default now());
create table public.task_history (id bigint generated always as identity primary key, task_id uuid not null references public.tasks(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, action text not null, old_data jsonb, new_data jsonb, created_at timestamptz not null default now());
create table public.events (id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade, project_id uuid references public.projects(id) on delete set null, title text not null, description text, start_at timestamptz not null, end_at timestamptz, all_day boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade, task_id uuid references public.tasks(id) on delete cascade, title text not null, message text, scheduled_at timestamptz, read_at timestamptz, created_at timestamptz not null default now());
create table public.user_settings (user_id uuid primary key references auth.users(id) on delete cascade, theme text not null default 'dark', locale text not null default 'pt-BR', timezone text not null default 'America/Sao_Paulo', browser_notifications boolean not null default false, updated_at timestamptz not null default now());
create index tasks_owner_status_idx on public.tasks(owner_id,status) where archived_at is null; create index tasks_owner_due_idx on public.tasks(owner_id,due_at) where archived_at is null;
create function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create trigger projects_touch before update on public.projects for each row execute function public.touch_updated_at(); create trigger tasks_touch before update on public.tasks for each row execute function public.touch_updated_at();
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',split_part(new.email,'@',1))); insert into public.user_settings(user_id) values(new.id); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create function public.log_task_change() returns trigger language plpgsql security definer set search_path=public as $$ begin if tg_op='INSERT' then insert into public.task_history(task_id,owner_id,action,new_data) values(new.id,new.owner_id,'created',to_jsonb(new)); elsif tg_op='UPDATE' then insert into public.task_history(task_id,owner_id,action,old_data,new_data) values(new.id,new.owner_id,'updated',to_jsonb(old),to_jsonb(new)); end if; return new; end $$;
create trigger task_audit after insert or update on public.tasks for each row execute function public.log_task_change();
